const bookings = $input.all();

let highest = 1000;

for (const item of bookings) {
  const id = item.json?.Booking_ID;

  if (!id) continue;

  const match = id.match(/^BK(\d+)$/);

  if (match) {
    const number = parseInt(match[1], 10);

    if (number > highest) {
      highest = number;
    }
  }
}

const nextNumber = highest + 1;

const bookingId = `BK${nextNumber}`;

return bookingId;
